 t.MapPost("/invoices/{id:guid}/late-fee",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService service)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var original=await service.Invoice(tenant,id,false);await service.Require(tenant,original.EntityId,original.UnitId,"finance.invoice");if(original.Status!="Issued"||original.Kind!="Invoice"||original.DueOn>=FinanceService.Today||original.Total<=original.Paid+original.Credited)throw new DomainException("Late fees require an overdue outstanding assessment");var assessment=await db.Set<DuesAssessment>().SingleOrDefaultAsync(d=>d.TenantId==tenant&&d.InvoiceId==id)??throw new DomainException("No snapshotted dues late-fee policy exists for this invoice");var snapshot=JsonSerializer.Deserialize<JsonElement>(assessment.Snapshot);if(!snapshot.TryGetProperty("LateFee",out var policy)||policy.GetDecimal()<=0)throw new DomainException("The issued assessment has no positive late-fee policy");var key="latefee:"+id;var prior=await db.Set<FinanceJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.EntityId==original.EntityId&&j.Key==key);if(prior!=null)return Results.Ok(new{id=prior.DocumentId});var invoice=await service.CreateInvoice(tenant,new(original.EntityId,original.UnitId!.Value,original.CounterpartyName,FinanceService.Today,FinanceService.Today.AddDays(7),[new("Authorized late fee for "+original.Number,1,policy.GetDecimal(),0,0,"4500")],original.MembershipId,original.BilledUnitId,original.DonorId,Purpose:"Late fee",Notes:"Separate assessment under the original snapshotted policy",Submit:true));invoice.OriginalId=id;db.Add(new FinanceJob{TenantId=tenant,EntityId=original.EntityId,UnitId=original.UnitId,Kind="LateFee",AuthorId=a.UserId,State="Completed",DocumentId=invoice.Id,Processed=1,Key=key});a.Audit(tenant,"finance.late-fee.requested",invoice.Id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(InvoiceDto(invoice));});
