 t.MapPost("/payments/{id:guid}/allocate",async(Guid tenant,Guid id,AllocationWrite r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var p=await db.Set<FinancePayment>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();await s.Require(tenant,p.EntityId,p.UnitId,"finance.collect");var invoice=await s.Invoice(tenant,r.InvoiceId,false);if(r.Key.Length is <3 or >160)throw new DomainException("Supply a stable allocation request key");await s.Require(tenant,invoice.EntityId,invoice.UnitId,"finance.collect");var result=await s.Allocate(p,invoice,r.Amount,r.Key,a.UserId);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(result);});
