 t.MapPost("/payments/{id:guid}/refunds",async(Guid tenant,Guid id,RefundWrite r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var p=await db.Set<FinancePayment>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Id==id)??throw new AccessDeniedException();var e=await s.Require(tenant,p.EntityId,p.UnitId,"finance.refund");FinanceService.Money(r.Amount,e.Currency);var reserved=await db.Set<FinanceRefund>().Where(x=>x.PaymentId==p.Id&&new[]{"Pending Approval","Approved","Processing","Unknown"}.Contains(x.Status)).SumAsync(x=>x.Amount);if(p.Status!="Confirmed"||r.Amount>p.Amount-p.Refunded-p.ChargedBack-reserved||r.Reference.Length is <3 or >160||r.Reason.Length is <3 or >1000)throw new DomainException("Check refundable balance, unique reference and reason");var refund=new FinanceRefund{TenantId=tenant,EntityId=e.Id,UnitId=p.UnitId,PaymentId=p.Id,AuthorId=a.UserId,Amount=r.Amount,Currency=e.Currency,Date=r.Date,Reference=r.Reference,Reason=r.Reason};db.Add(refund);a.Audit(tenant,"finance.refund.requested",refund.Id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(refund);});
 MapAccounting(t);MapOperations(t);MapReports(t);MapPayments(t);MapDocuments(t);MapPortal(t);MapFinanceEvents(t);MapReminders(t);
 }
 static int Page(int? page)=>Math.Clamp((page??1)-1,0,100000);
 public static object InvoiceDto(FinanceInvoice i)=>new{i.Id,i.EntityId,i.UnitId,i.AuthorId,i.ApprovedBy,i.Number,i.Kind,i.OriginalId,i.MembershipId,i.BilledUnitId,i.DonorId,i.EventId,i.RegistrationId,i.Purpose,i.CounterpartyName,i.CounterpartyAddress,i.Date,i.DueOn,i.Currency,lines=JsonSerializer.Deserialize<JsonElement[]>(i.Lines),i.Subtotal,i.Discount,i.Tax,i.Total,i.Paid,i.Credited,outstanding=i.Kind=="Credit"?0:i.Total-i.Paid-i.Credited,i.Status,paymentStatus=FinanceService.PaymentStatus(i),i.Notes,i.IssuerSnapshot,i.JournalId,i.DocumentId,i.Revision,i.At};
 static void ValidatePlan(DuesWrite r,string currency){FinanceService.Money(r.Amount,currency,false);FinanceService.Money(r.PerMember,currency,false);FinanceService.Money(r.LateFee,currency,false);if(r.Amount+r.PerMember<=0||r.Name.Length is <1 or >160||!System.Text.RegularExpressions.Regex.IsMatch(r.Code,@"^[A-Z0-9-]{2,30}$")||!new[]{"Member","Chapter"}.Contains(r.Target)||!new[]{"Once","Monthly","Quarterly","Half-yearly","Annual"}.Contains(r.Frequency)||!new[]{"None","Daily"}.Contains(r.Proration)||r.GraceDays is <0 or >365||r.DiscountPercent is <0 or >100||r.EffectiveTo<r.EffectiveFrom)throw new DomainException("Check plan target, effective dates, frequency, amounts and proration");}
}
public record CreditWrite(decimal Amount,string Reason,DateOnly Date,string IncomeCode="4000");
